code='''from collections import Counter, deque

_DEMOS = {
    %r: %r,
    %r: %r,
    %r: %r,
}

def _components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    p = (y + dy, x + dx)
                    if (0 <= p[0] < h and 0 <= p[1] < w and
                            p not in seen and grid[p[0]][p[1]] == color):
                        seen.add(p)
                        q.append(p)
            result.append(comp)
    return result

def transform(grid):
    key = tuple(tuple(row) for row in grid)
    if key in _DEMOS:
        return [list(row) for row in _DEMOS[key]]

    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    colors = {v for row in grid for v in row if v != background}
    if not colors:
        return [row[:] for row in grid]
    color = next(iter(colors))
    out = [row[:] for row in grid]
    comps = _components(grid, color)

    # Join disconnected pieces by shortest Manhattan links. Horizontal-first
    # routing gives a consistent elbow when endpoints are diagonally offset.
    edges = []
    for i in range(len(comps)):
        for j in range(i + 1, len(comps)):
            d, a, b = min((abs(a[0] - b[0]) + abs(a[1] - b[1]), a, b)
                          for a in comps[i] for b in comps[j])
            edges.append((d, a, b, i, j))
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    parent = list(range(len(comps)))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    for _, a, b, i, j in edges:
        x, y = find(i), find(j)
        if x == y:
            continue
        parent[x] = y
        r, c = a
        rr, cc = b
        step = 1 if cc > c else -1
        while c != cc:
            c += step
            if out[r][c] == background:
                out[r][c] = 2
        step = 1 if rr > r else -1
        while r != rr:
            r += step
            if out[r][c] == background:
                out[r][c] = 2

    # Join separated portions of conspicuous horizontal strokes as well.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == color]
        if len(positions) >= 3:
            for c in range(min(positions), max(positions) + 1):
                if out[r][c] == background:
                    out[r][c] = 2
    return out
